const EXPECTED_OBJECTIVE_COUNTS = Object.freeze({
  "PGCR.1": 18,
  "PGCR.2": 26,
  "PGCR.3": 14,
  "PGCR.4": 14,
  "PGCR.5": 22,
  "PGCR.6": 16,
  "PGCR.7": 14,
  "PGCR.8": 20,
  "PGCR.9": 16
});

const ORDINARY_DIFFICULTY_QUOTAS = Object.freeze({ easy: 44, medium: 52, hard: 32, elite: 12, legendary: 12 });
const DIFFICULTY_CYCLE = ["easy", "medium", "hard", "medium", "easy", "medium", "elite", "hard", "medium", "legendary"];

function buildDifficultyPlan(count) {
  const remaining = { ...ORDINARY_DIFFICULTY_QUOTAS };
  const plan = [];
  let cursor = 0;
  while (plan.length < count) {
    const candidate = DIFFICULTY_CYCLE[cursor % DIFFICULTY_CYCLE.length];
    cursor += 1;
    if (remaining[candidate] > 0) {
      plan.push(candidate);
      remaining[candidate] -= 1;
    }
  }
  if (Object.values(remaining).some(value => value !== 0)) throw new Error(`Difficulty plan did not exhaust quotas: ${JSON.stringify(remaining)}`);
  return plan;
}

function assignPool(difficulty, seen) {
  seen[difficulty] = (seen[difficulty] || 0) + 1;
  if (seen[difficulty] <= 4) {
    if (difficulty === "easy") return "easyBoss";
    if (difficulty === "medium") return "mediumBoss";
    if (difficulty === "hard") return "finalBoss";
    if (difficulty === "legendary") return "legendaryBoss";
  }
  return difficulty;
}

const allRows = [...GRAPH_QUESTIONS, ...NON_GRAPH_QUESTIONS];
const ordinaryRows = allRows.filter(question => !question.support);
const difficultyPlan = buildDifficultyPlan(ordinaryRows.length);
const poolSeen = {};
let ordinaryIndex = 0;

export const productionQuestions = allRows.map((question, index) => {
  const supportPool = question.support === "repair" ? "repairQuestions" : question.support === "bridge" ? "bridgeQuestions" : null;
  const difficulty = supportPool ? "medium" : difficultyPlan[ordinaryIndex++];
  const pool = supportPool || assignPool(difficulty, poolSeen);
  return {
    id: ID_FIRST + index,
    q: question.q,
    answer: question.answer,
    distractors: question.distractors,
    objective: question.objective,
    objectiveLabel: OBJECTIVES[question.objective],
    primarySkill: question.primarySkill,
    secondarySkills: [],
    repairSkill: question.primarySkill,
    difficulty,
    pool,
    type: supportPool === "bridgeQuestions" ? "bridge" : question.type,
    tag: question.subtopic,
    conceptCluster: CONCEPT_ID,
    commonError: COMMON_ERRORS[question.objective],
    feedback: question.feedback,
    graphRequired: Boolean(question.asset),
    asset: question.asset || null,
    scenario: question.asset ? GRAPH_ASSETS[question.asset].scenario : null
  };
});

if (productionQuestions.length !== 160) throw new Error(`Expected 160 production questions; found ${productionQuestions.length}.`);
if (productionQuestions.at(-1).id !== ID_LAST) throw new Error(`Expected final ID ${ID_LAST}; found ${productionQuestions.at(-1).id}.`);
if (GRAPH_QUESTIONS.length !== 48) throw new Error(`Expected 48 graph questions; found ${GRAPH_QUESTIONS.length}.`);
const objectiveCounts = productionQuestions.reduce((counts, question) => {
  counts[question.objective] = (counts[question.objective] || 0) + 1;
  return counts;
}, {});
if (Object.entries(EXPECTED_OBJECTIVE_COUNTS).some(([objective, count]) => objectiveCounts[objective] !== count)) {
  throw new Error(`Objective distribution mismatch: ${JSON.stringify(objectiveCounts)}`);
}
const supportCounts = productionQuestions.reduce((counts, question) => {
  counts[question.pool] = (counts[question.pool] || 0) + 1;
  return counts;
}, {});
if (supportCounts.repairQuestions !== 4 || supportCounts.bridgeQuestions !== 4) {
  throw new Error(`Expected four repair and four bridge records; found ${JSON.stringify(supportCounts)}.`);
}
